// Harness: runs the verbatim-extracted dns_parse_name from
// /app/rust/src/dns/parser.rs against the incident corpus.
use nom7::error::ErrorKind;
use nom7::multi::length_data;
use nom7::number::streaming::{be_u16, be_u8};
use nom7::{error_position, Err, IResult};

bitflags::bitflags! {
    #[derive(Default)]
    pub struct DNSNameFlags: u8 {
        const INFINITE_LOOP = 0b0000_0001;
        const TRUNCATED     = 0b0000_0010;
        const LABEL_LIMIT   = 0b0000_0100;
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DNSName {
    pub value: Vec<u8>,
    pub flags: DNSNameFlags,
}

include!("extracted.rs");

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn main() {
    let mut m6: Vec<u8> = Vec::new();
    for _ in 0..16 {
        m6.push(63);
        m6.extend(std::iter::repeat(b'a').take(63));
    }
    m6.push(16);
    m6.extend(std::iter::repeat(b'a').take(16));
    m6.push(0x00);

    let corpus: Vec<(&str, usize, Vec<u8>)> = vec![
        ("m1", 12, unhex("000101000001000000000000076578616d706c6503636f6d0000010001")),
        ("m2", 12, unhex("00010100000100000000000003677777076578616d706c6503636f6d0000010001")),
        ("m3", 12, unhex("00010100000100000000000003777777c012076578616d706c6503636f6d0000010001")),
        ("m4", 12, unhex("000101000001000000000000c00c00010001")),
        ("m5", 0, unhex("c000")),
        ("m6", 0, m6),
        ("m7", 12, unhex("0001010000010000000000000161c00c00010001")),
        ("m8", 0, unhex("00")),
        ("m9", 0, unhex("0161c000")),
        ("m10", 0, unhex("ff6161")),
    ];

    for (id, offset, message) in &corpus {
        let mut flags = DNSNameFlags::default();
        match dns_parse_name(&message[*offset..], message, &mut flags) {
            Ok((_rem, name)) => {
                println!(
                    "{}\tok=true\ttrunc={}\tloop={}\tlimit={}\tlen={}\tname={}",
                    id,
                    name.flags.contains(DNSNameFlags::TRUNCATED),
                    name.flags.contains(DNSNameFlags::INFINITE_LOOP),
                    name.flags.contains(DNSNameFlags::LABEL_LIMIT),
                    name.value.len(),
                    name.value.iter().map(|b| *b as char).collect::<String>()
                );
            }
            Err(_) => {
                println!("{}\tok=false\ttrunc=false\tloop=false\tlimit=false\tlen=0\tname=", id);
            }
        }
    }
}

